(* [comment removed for export] *)
Lemma sched_shutdown_spec : asched_shutdown_stmt H.
Proof.
  intros s S lo shi LB LF Sv. intros until m. intros SCH LK HP ST LO CEIL RA MI SPAL TPV AC RF LFN SK SHI.
  eapply shut_pro; [exact SCH| exact HP| exact ST| exact LO| exact CEIL| exact MI| exact SPAL| exact TPV| exact AC| exact RF| exact LFN| exact SK|].
  intros m2 spa gap p0 p8 p24 pL h32 j88 shb ff fp. intros until xs11. intros LOC GAP GSZ SPAC SAVED FRM SHU FL ST2 MI2 RF2 FF AC2 SK2 MU2 WM2 SCH2 HP2.
  eapply (shut_mid H HH); [exact LOC| exact GAP| exact GSZ| exact SPAC| exact SAVED| exact FRM| exact SHU| exact FL| exact ST2| exact MI2| exact RF2| exact FF| exact AC2| exact SK2
    | exact MU2| exact WM2| exact SCH2| exact LK| exact HP2| exact RF| exact LO| exact CEIL| exact RA| exact SPAL| exact SHI].
Qed.

